  const detach = options?.detach ?? Boolean(options?.routePath);
  if (!detach) {
    const appUrl = `http://127.0.0.1:${runtime.port}${routePath}`;
    const status = await getReviewStudioRuntimeStatus(runtime);
    if (status.running) {
      if (!status.runtime) {
